def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    return divs

def solve():
    a1 = 2024
    for D in range(7975, 0, -1):
        temp_D = D
        prime_powers = []
        d = 2
        while d * d <= temp_D:
            if temp_D % d == 0:
                p_e = 1
                while temp_D % d == 0:
                    p_e *= d
                    temp_D //= d
                prime_powers.append(p_e)
            d += 1
        if temp_D > 1:
            prime_powers.append(temp_D)

        required_congruences = []
        for p_e in prime_powers:
            if a1 % p_e != 0:
                required_congruences.append((a1 % p_e, p_e))

        if not required_congruences:
            return D

        F_val = 0
        M = 1
        possible = True
        for r, m in required_congruences:
            try:
                inv_M = pow(M, -1, m)
                k = ((r - F_val) * inv_M) % m
                F_val = F_val + M * k
                M *= m
            except ValueError:
                possible = False
                break

        if not possible:
            continue

        # F = F_val + k * M
        # We need F in [2025 + D, 10000]
        # F_val + k * M >= 2025 + D  =>  k >= (2025 + D - F_val) / M
        # F_val + k * M <= 10000  =>  k <= (10000 - F_val) / M

        min_k = (2025 + D - F_val + M - 1) // M if 2025 + D - F_val > 0 else (2025 + D - F_val) // M
        max_k = (10000 - F_val) // M

        if min_k <= max_k:
            return D
    return 0

print(solve())
